data.script:
function check(value,message){if(!value)throw Error(message);}
const before=editor.getText();
const source='https://old.example:8443/path?q=one#old';
const first=URL.parse(source),second=URL.parse(source);
check(first instanceof URL&&first.hostname==='old.example','typed parse');
first.fragment='new';
check(first.fragment==='#new'&&first.href==='https://old.example:8443/path?q=one#new','fragment coherence');
first.hostname='new.example';
check(first.host==='new.example:8443'&&String(first)==='https://new.example:8443/path?q=one#new','hostname coherence');
check(JSON.parse(JSON.stringify(first)).hostname==='new.example','enumerable hostname');
check(second.href===source&&second.fragment==='#old','independent objects');
const relative=URL.parse('../next?q=boo#section','https://example.com/folder/page');
check(relative.href==='https://example.com/next?q=boo#section'&&relative.searchParams.q==='boo','base resolution');
check(editor.getText()===before,'editor preserved');
console.log('URL component coherence passed café 🐼');
